import{_ as e,o as a,c as r,a6 as s}from"./chunks/framework.DPQO9SRd.js";const p=JSON.parse('{"title":"Sales Tax Glossary","description":"Short definitions of the sales tax and TaxJar terms in these docs, from AutoFile and nexus to exemption, product tax category, sync and Sandbox mode.","frontmatter":{"title":"Sales Tax Glossary","description":"Short definitions of the sales tax and TaxJar terms in these docs, from AutoFile and nexus to exemption, product tax category, sync and Sandbox mode.","type":"reference","pageClass":"glossary-page"},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md"}'),o={name:"reference/glossary.md"};function n(d,t,i,h,c,l){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><h2 id="sales-tax" tabindex="-1">Sales Tax <a class="header-anchor" href="#sales-tax" aria-label="Permalink to &quot;Sales Tax&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Destination-based tax</strong></td><td>The state uses the rate of the ship-to address.</td></tr><tr><td><strong>Exemption</strong></td><td>A customer or a sale that pays no sales tax, for example a reseller. Refer to <a href="/usa/sales-tax/pr-preview/pr-29/tax-exemptions/customer-tax-exemption">Customer Tax Exemption</a>.</td></tr><tr><td><strong>Exempt region</strong></td><td>A US state or Canadian province where a customer&#39;s exemption applies.</td></tr><tr><td><strong>Export</strong></td><td>A sale with a ship-to country that is not the United States. It has no US sales tax.</td></tr><tr><td><strong>Jurisdiction</strong></td><td>A level of government that charges sales tax: the state, the county, the city or a special district.</td></tr><tr><td><strong>Nexus</strong></td><td>A legal connection to a state. You collect sales tax only in your nexus states. Refer to <a href="/usa/sales-tax/pr-preview/pr-29/setting-up/updating-your-nexus">Updating your nexus</a>.</td></tr><tr><td><strong>Origin-based tax</strong></td><td>The state uses the rate of the ship-from address.</td></tr><tr><td><strong>Product tax category</strong></td><td>A TaxJar code that tells TaxJar how states tax an item. Refer to <a href="/usa/sales-tax/pr-preview/pr-29/tax-exemptions/item-tax-exemption">Item Tax Exemption</a>.</td></tr></tbody></table><h2 id="documents-sync" tabindex="-1">Documents &amp; Sync <a class="header-anchor" href="#documents-sync" aria-label="Permalink to &quot;Documents &amp; Sync&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Credit note</strong></td><td>A sales invoice with <strong>Is Return (Credit Note)</strong> set. TaxJar records it as a refund. Refer to <a href="/usa/sales-tax/pr-preview/pr-29/sales-adjustments/credit-and-debit-notes">Credit &amp; Debit Notes</a>.</td></tr><tr><td><strong>Debit note</strong></td><td>A sales invoice that adds an amount to an earlier invoice. TaxJar records it as an order.</td></tr><tr><td><strong>Ship from</strong></td><td>The company address with <strong>Preferred Billing Address</strong> set.</td></tr><tr><td><strong>Ship to</strong></td><td>The shipping address of the document. If it is empty, the app asks for one when you save.</td></tr><tr><td><strong>Sync</strong></td><td>The app sends a submitted invoice, credit note or customer to TaxJar. Refer to <a href="/usa/sales-tax/pr-preview/pr-29/transaction-sync/syncing-to-taxjar">Syncing to TaxJar</a>.</td></tr><tr><td><strong>TaxJar Sales Tax template</strong></td><td>The tax template that TaxJar Setup makes for each company, with a shipping row and a sales tax row.</td></tr><tr><td><strong>Transaction</strong></td><td>An order or a refund in TaxJar, made from an invoice or a credit note.</td></tr></tbody></table><h2 id="taxjar-account" tabindex="-1">TaxJar Account <a class="header-anchor" href="#taxjar-account" aria-label="Permalink to &quot;TaxJar Account&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>API token</strong></td><td>The key from TaxJar that lets the app use one TaxJar account. Each company has a Live token and a Sandbox token.</td></tr><tr><td><strong>AutoFile</strong></td><td>A TaxJar service that files your sales tax returns from the transactions in your TaxJar account.</td></tr><tr><td><strong>Live mode</strong></td><td>The API mode for real business. TaxJar records the transactions. Refer to <a href="/usa/sales-tax/pr-preview/pr-29/setting-up/before-you-go-live">Before you go live</a>.</td></tr><tr><td><strong>Persona</strong></td><td>A type of TaxJar user: TaxJar Manager or TaxJar User. It is not an ERPNext role. Refer to <a href="/usa/sales-tax/pr-preview/pr-29/setting-up/roles-and-permissions">Roles &amp; Permissions</a>.</td></tr><tr><td><strong>Sandbox mode</strong></td><td>The API mode for tests. TaxJar does not record the transactions.</td></tr></tbody></table>',7)])])}const g=e(o,[["render",n]]);export{p as __pageData,g as default};
